  let msg = ts.flattenDiagnosticMessageText(d.messageText, ' ');
  if (d.file && d.start != null) {
    const p = d.file.getLineAndCharacterOfPosition(d.start);
    msg = 'line ' + (p.line + 1) + ': ' + msg;
  }
